from pathlib import Path
import subprocess,json
name='optima-metadata-streaming';unit='[Unit]\nDescription=Isolated disk-backed validation for oversized metadata artifacts\nAfter=network-online.target\n[Service]\nType=oneshot\nUser=ec2-user\nWorkingDirectory=/opt/constellation/metadata-engine-runtime\nExecStart=/opt/constellation/legacy-venv/bin/python -B -m metadata_engine.streaming_worker --max-jobs 4\nSlice=constellation-workers.slice\nMemoryHigh=671088640\nMemoryMax=805306368\nMemorySwapMax=0\nCPUQuota=75%\nTimeoutStartSec=900\nTimeoutStopSec=20\nEnvironment=PYTHONDONTWRITEBYTECODE=1\nEnvironment=MALLOC_ARENA_MAX=2\n';timer='[Unit]\nDescription=Continue oversized metadata artifacts independently\n[Timer]\nOnBootSec=120\nOnUnitInactiveSec=60\nUnit='+name+'.service\n[Install]\nWantedBy=timers.target\n'
for suffix,body in (('.service',unit),('.timer',timer)):Path('/etc/systemd/system/'+name+suffix).write_text(body)
subprocess.run(['systemctl','daemon-reload'],check=True);subprocess.run(['systemctl','enable','--now',name+'.timer'],check=True);subprocess.run(['systemctl','start','--no-block',name+'.service'],check=True);print('Isolated streaming timer enabled.')
